import {
  forwardRef,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";

import { useInheritedRadius } from "./hooks/use-inherited-radius";
import { useReducedMotion } from "./hooks/use-reduced-motion";
import { sampleInkColor } from "./style-observer";
import { ensureMotionStyles } from "./styles";
import { motionTokens } from "./tokens";

export interface RippleProps {
  children: ReactNode;
  /**
   * 0..1 — ripple strength (peak opacity of the expanding circle).
   * @default motionTokens.intensity.ripple
   */
  intensity?: number;
  /**
   * Ripple color. Defaults to the wrapped element's computed text
   * color, sampled at press time — the "ink" that reads correctly on
   * any solid background (accent buttons get a foreground ripple,
   * outline buttons get a text-colored one). Pass a value to override.
   */
  color?: string;
  /** Disable the ripple. @default false */
  disabled?: boolean;
  /** Ripple duration in ms. @default motionTokens.duration.slow */
  duration?: number;
  /**
   * Always expand from the element center instead of the pointer
   * position. Useful for icon buttons and other symmetric controls.
   * @default false
   */
  centered?: boolean;
  className?: string;
  style?: CSSProperties;
}

interface RippleInstance {
  id: number;
  x: number;
  y: number;
  radius: number;
  color: string;
}

/**
 * Ripple — a radial expanding circle on press, like the Mode Switcher's
 * radial reveal but contained to the wrapped element.
 *
 * Implementation: on pointerdown (or Enter/Space for keyboard users) a
 * circular span spawns at the press position and animates scale 0 → 1 via
 * shared `@keyframes ionbit-ui-ripple`, fading out at the end. The span is
 * removed on `animationend`. The circle is sized to reach the element's
 * farthest corner and clipped by the wrapper's `overflow: hidden`, which
 * inherits the wrapped element's border-radius automatically.
 *
 * Reduced motion: no ripple is spawned; the control still works normally.
 *
 * The wrapper is an inline-flex span — for block-level content like cards,
 * pass `className="flex"` (or another display) so the wrapper covers it.
 */
export const Ripple = forwardRef<HTMLSpanElement, RippleProps>(function Ripple(
  {
    children,
    intensity = motionTokens.intensity.ripple,
    color,
    disabled = false,
    duration = motionTokens.duration.slow,
    centered = false,
    className,
    style,
  },
  ref,
) {
  const radiusRef = useInheritedRadius<HTMLSpanElement>();
  const reduced = useReducedMotion();
  const idRef = useRef(0);
  const [ripples, setRipples] = useState<RippleInstance[]>([]);

  ensureMotionStyles();

  useEffect(() => {
    const el = radiusRef.current;
    if (!el || disabled || reduced) return;

    const spawn = (clientX?: number, clientY?: number) => {
      const rect = el.getBoundingClientRect();
      const fromCenter = centered || clientX === undefined;
      const x = fromCenter ? rect.width / 2 : clientX! - rect.left;
      const y = fromCenter ? rect.height / 2 : clientY! - rect.top;
      const radius = Math.hypot(
        Math.max(x, rect.width - x),
        Math.max(y, rect.height - y),
      );
      setRipples((rs) => [
        ...rs,
        { id: ++idRef.current, x, y, radius, color: resolveColor() },
      ]);
    };

    const resolveColor = () => color ?? sampleInkColor(el);

    const onPointerDown = (e: PointerEvent) => {
      if (e.button !== 0) return;
      spawn(e.clientX, e.clientY);
    };

    const onKeyDown = (e: globalThis.KeyboardEvent) => {
      if (e.key !== "Enter" && e.key !== " ") return;
      spawn();
    };

    el.addEventListener("pointerdown", onPointerDown);
    el.addEventListener("keydown", onKeyDown);
    return () => {
      el.removeEventListener("pointerdown", onPointerDown);
      el.removeEventListener("keydown", onKeyDown);
    };
  }, [radiusRef, disabled, reduced, centered, color]);

  const setRef = (el: HTMLSpanElement | null) => {
    radiusRef.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref) ref.current = el;
  };

  if (disabled) return <>{children}</>;

  const remove = (id: number) =>
    setRipples((rs) => rs.filter((r) => r.id !== id));

  return (
    <span
      ref={setRef}
      className={className}
      style={{
        display: "inline-flex",
        position: "relative",
        overflow: "hidden",
        // Buttons shift down 1px on :active — give the clip area 1px of
        // slack so the bottom edge isn't cut. The negative margin keeps
        // the wrapper's outer size unchanged.
        paddingBlockEnd: 1,
        marginBlockEnd: -1,
        ...style,
      }}
    >
      {children}
      {ripples.map((r) => (
        <span
          key={r.id}
          aria-hidden="true"
          data-ionbit-ripple=""
          onAnimationEnd={() => remove(r.id)}
          style={{
            position: "absolute",
            left: r.x - r.radius,
            top: r.y - r.radius,
            width: r.radius * 2,
            height: r.radius * 2,
            borderRadius: "50%",
            background: r.color,
            pointerEvents: "none",
            animation: `ionbit-ui-ripple ${duration}ms var(--ease-standard, ease-out) forwards`,
            ["--ripple-opacity" as string]: 0.24 * intensity,
          }}
        />
      ))}
    </span>
  );
});

import { useEffect, useRef, type MutableRefObject } from "react";

import { observeStyleChanges } from "../style-observer";

export interface UseInheritedRadiusOptions<T extends HTMLElement> {
  /**
   * Resolve the element whose computed border-radius should be
   * mirrored. Defaults to the wrapper's `firstElementChild` — override
   * when the wrapper's DOM contains non-content siblings (e.g.
   * overlay layers) before the real content.
   */
  resolveChild?: (el: T) => HTMLElement | null;
}

/**
 * Reads the content child's computed border-radius and applies it to
 * the wrapper element. This lets motion wrappers (Glow, Pulse,
 * Spotlight, Tilt, Ripple) automatically match the wrapped element's
 * rounded corners without requiring the user to pass a `className`
 * for the radius.
 *
 * The radius is re-sampled when the document's styles change (injected
 * stylesheets, root attribute/class changes — e.g. theme switches) and
 * on `pointerenter`, so live theme updates don't require a reload.
 *
 * @returns A ref to attach to the wrapper element.
 */
export function useInheritedRadius<T extends HTMLElement = HTMLElement>(
  options?: UseInheritedRadiusOptions<T>,
): MutableRefObject<T | null> {
  const ref = useRef<T | null>(null);
  const optionsRef = useRef(options);
  optionsRef.current = options;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const sample = () => {
      const child = (optionsRef.current?.resolveChild?.(el) ??
        el.firstElementChild) as HTMLElement | null;
      if (!child) return;

      const childRadius = getComputedStyle(child).borderRadius;
      if (childRadius && el.style.borderRadius !== childRadius) {
        el.style.borderRadius = childRadius;
      }
    };

    sample();

    return observeStyleChanges(el, sample);
  }, []);

  return ref;
}

/**
 * Samples the wrapped element's computed text color — the "ink" that
 * reads correctly on any solid background. Used by Ripple (ripple
 * color) and Tilt (reflection glare) so effects follow the element's
 * own foreground on both light and dark surfaces.
 *
 * Reads `firstElementChild` (the wrapped content), falling back to
 * the wrapper itself, and returns `fallback` when the computed color
 * is empty or fully transparent.
 */
export function sampleInkColor(
  el: HTMLElement,
  fallback = "currentColor",
): string {
  const target = (el.firstElementChild ?? el) as HTMLElement;
  const computed = getComputedStyle(target).color;
  return computed && computed !== "transparent" ? computed : fallback;
}

/**
 * Invokes `callback` whenever the document's styles could have changed:
 * injected/replaced stylesheets in `<head>`, attribute/class mutations
 * on the root element (e.g. `.dark` mode toggles, theme classes), and
 * on `pointerenter` of `el` as a fallback for class-driven style
 * changes the document observers cannot see.
 *
 * Used by primitives that sample computed styles (inherited radius,
 * inherited text color) so live theme updates don't require a reload.
 *
 * @returns A cleanup function that disconnects all listeners.
 */
export function observeStyleChanges(
  el: HTMLElement,
  callback: () => void,
): () => void {
  const observer = new MutationObserver(callback);
  observer.observe(document.head, {
    childList: true,
    characterData: true,
    subtree: true,
  });
  observer.observe(document.documentElement, { attributes: true });
  el.addEventListener("pointerenter", callback);

  return () => {
    observer.disconnect();
    el.removeEventListener("pointerenter", callback);
  };
}

import { useEffect, useState } from "react";

/**
 * Returns `true` when the user has requested reduced motion via the OS / browser.
 *
 * All Ionbit UI motion primitives use this to self-disable. Components should
 * never animate transform/opacity in a way that distracts under reduced motion.
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(() => {
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  });

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const handler = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  return reduced;
}

// Single global <style> tag for all motion primitives.
// Injected once on first use; subsequent calls are no-ops.

const STYLES = `
/* Reveal — toggled via data-revealed attribute by IntersectionObserver. */
[data-digital-reveal][data-revealed="true"] {
  opacity: 1 !important;
  transform: none !important;
}

/* Glow — hover/focus/always-driven box-shadow or text-shadow.
   Triggers are controlled via data-glow-hover, data-glow-focus and
   data-glow-always; the shadow value is set as a CSS custom property
   on the element. */
[data-digital-glow][data-glow-hover="true"][data-glow-variant="halo"]:hover,
[data-digital-glow][data-glow-focus="true"][data-glow-variant="halo"]:focus-within,
[data-digital-glow][data-glow-always="true"][data-glow-variant="halo"] {
  box-shadow: var(--glow-shadow);
}

[data-digital-glow][data-glow-hover="true"][data-glow-variant="text"]:hover,
[data-digital-glow][data-glow-focus="true"][data-glow-variant="text"]:focus-within,
[data-digital-glow][data-glow-always="true"][data-glow-variant="text"] {
  text-shadow: var(--glow-text-shadow);
}

/* When the wrapped control presses down on :active (e.g. Button's
   translate-y-px), move the whole unit — element + halo — together:
   the wrapper takes over the 1px shift and the child's own active
   translate/transform is neutralized so it doesn't apply twice. */
[data-digital-glow]:has(> :active) {
  translate: 0 1px;
}
[data-digital-glow][data-glow-variant] > :active {
  translate: none;
  transform: none;
}

/* Pulse — single shared keyframes; intensity controlled via CSS vars. */
@keyframes ionbit-ui-pulse-halo {
  0%, 100% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--pulse-color) 0%, transparent);
  }
  50% {
    box-shadow: 0 0 var(--pulse-blur) var(--pulse-spread)
      color-mix(in oklab, var(--pulse-color) var(--pulse-alpha), transparent);
  }
}

@keyframes ionbit-ui-pulse-text {
  0%, 100% {
    text-shadow: 0 0 0 color-mix(in oklab, var(--pulse-color) 0%, transparent);
  }
  50% {
    text-shadow: 0 0 var(--pulse-blur)
      color-mix(in oklab, var(--pulse-color) var(--pulse-alpha), transparent);
  }
}

/* Ripple — circle expands from the press point to cover the element,
   then fades out. Peak opacity is set per-instance via --ripple-opacity.
   The span is removed on animationend. */
@keyframes ionbit-ui-ripple {
  0% {
    transform: scale(0);
    opacity: var(--ripple-opacity, 0.24);
  }
  60% {
    transform: scale(1);
    opacity: var(--ripple-opacity, 0.24);
  }
  100% {
    transform: scale(1);
    opacity: 0;
  }
}

/* Trace — an accent beam travels along the element's border. The beam
   overlay paints a conic-gradient masked to the border ring; rotating
   --ionbit-trace-angle moves the bright segment around the perimeter.
   @property registration is required for the angle to interpolate —
   browsers without it get a static beam (graceful degradation). */
@property --ionbit-trace-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@keyframes ionbit-ui-trace {
  to {
    --ionbit-trace-angle: 1turn;
  }
}
`;

let injected = false;

export function ensureMotionStyles(): void {
  if (injected || typeof document === "undefined") return;
  const existing = document.getElementById("ionbit-ui-motion-styles");
  if (existing) {
    // Refresh stale content — after HMR the module-level `injected` flag
    // resets but the old <style> tag persists with outdated rules.
    if (existing.textContent !== STYLES) existing.textContent = STYLES;
    injected = true;
    return;
  }
  const el = document.createElement("style");
  el.id = "ionbit-ui-motion-styles";
  el.textContent = STYLES;
  document.head.appendChild(el);
  injected = true;
}

/**
 * Ionbit UI — Motion tokens
 *
 * The single source of truth for timing, easing, spring, and intensity.
 * Components and primitives reference these; they do not hardcode values.
 *
 * These mirror the CSS variables in @ionbit-ui/tokens so JS-driven
 * animations (Motion) and CSS-driven animations stay in sync.
 */

export const motionTokens = {
  duration: {
    fast: 140,
    normal: 220,
    slow: 420,
  },
  easing: {
    standard: [0.2, 0.8, 0.2, 1] as const,
    emphasized: [0.3, 0, 0, 1] as const,
    exit: [0.4, 0, 1, 1] as const,
  },
  spring: {
    magnetic: { stiffness: 200, damping: 15, mass: 0.3 },
    gentle: { stiffness: 120, damping: 20, mass: 0.4 },
  },
  intensity: {
    glow: 0.7,
    magnetic: 0.2,
    pulse: 0.65,
    ripple: 0.3,
    scramble: 0.6,
    spotlight: 0.4,
    tilt: 0.5,
    tiltReflection: 0.35,
    trace: 0.6,
  },
} as const;

export type MotionTokens = typeof motionTokens;
